function updateUsdIdr(){const value=document.querySelector("#usd-idr-rate"),time=document.querySelector("#usd-idr-time"),setRate=(rate,label)=>{value.textContent=`1 USD = ${new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(rate).replace("Rp","Rp ")}`;time.textContent=label};fetch("https://api.frankfurter.dev/v2/rate/USD/IDR",{cache:"no-store"}).then(response=>{if(!response.ok)throw new Error("Rate feed unavailable");return response.json()}).then(data=>{const rate=Number(data.rate||data.rates?.IDR);if(!Number.isFinite(rate))throw new Error("Invalid rate feed");setRate(rate,`Updated ${new Intl.DateTimeFormat("id-ID",{hour:"2-digit",minute:"2-digit"}).format(new Date())}`)}).catch(()=>setRate(15850,"Indicative fallback"))}
