function title(name,sub,actions=""){return `<div class="heading"><div><h1>${name}</h1><p>${sub}</p></div><div class="toolbar">${actions}</div></div>`}
function controls(){return `<button class="chip active">Today</button><button class="chip">Daily</button><button class="chip">Weekly</button><button class="chip">Monthly</button><button class="chip">Since inception</button><select><option>IDR</option><option>USD</option></select><select><option>All assets</option><option>USDT</option><option>USDC</option><option>BTC</option></select>`}
function kpis(){const t=totals();return `<div class="kpis section"><div class="kpi"><label>OTC total volume</label><strong>${money(t.vol)}</strong><span>Ledger derived</span></div><div class="kpi"><label>Fiat IN</label><strong>${money(t.fiatIn)}</strong><span>Bank settled inflow</span></div><div class="kpi"><label>Fiat OUT</label><strong>${money(t.fiatOut)}</strong><span>Bank settled outflow</span></div><div class="kpi"><label>Crypto IN</label><strong>${t.cryptoIn.toLocaleString()} USDT</strong><span>Wallet ledger</span></div><div class="kpi"><label>Crypto OUT</label><strong>${t.cryptoOut.toLocaleString()} USDT</strong><span>Wallet ledger</span></div><div class="kpi"><label>Net brokerage revenue</label><strong>Rp 2.14 B</strong><span>Fee and spread</span></div><div class="kpi"><label>Managed assets AUM</label><strong>Rp 312.8 B</strong><span>Current IDR equivalent</span></div><div class="kpi"><label>Transactions</label><strong>${t.count}</strong><span>1 exception needs action</span></div></div>`}
function dashboard(){const t=totals();view.innerHTML=title("OTC Management Dashboard","Executive monitoring across the master transaction ledger.",controls())+kpis()+`<div class="grid section"><section class="card"><div class="split"><div><h2>OTC flow monitoring</h2><p class="sub">Bank and on-chain flows reconciled to the same ledger.</p></div><span class="eyebrow">Live control view</span></div><div class="flow"><div class="flow-col"><div class="flow-node in"><span class="eyebrow">Bank IN</span><b>${money(t.fiatIn)}</b></div><div class="flow-node out"><span class="eyebrow">Bank OUT</span><b>${money(t.fiatOut)}</b></div></div><div class="core">PT LINTAS BATAS PEMBAYARAN<small>OTC treasury core · controlled settlement</small></div><div class="flow-col"><div class="flow-node in"><span class="eyebrow">Crypto IN</span><b>${t.cryptoIn.toLocaleString()} USDT</b></div><div class="flow-node out"><span class="eyebrow">Crypto OUT</span><b>${t.cryptoOut.toLocaleString()} USDT</b></div></div></div></section><section class="card"><h2>Control status</h2><p class="sub">Daily operating controls</p><div class="metric"><span>Bank reconciliation</span><b>99.1% ${pill("Reconciled")}</b></div><div class="metric"><span>Wallet reconciliation</span><b>99.7% ${pill("Reconciled")}</b></div><div class="metric"><span>KYC AML queue</span><b>02 ${pill("Review")}</b></div><div class="metric"><span>Open exceptions</span><b>01 ${pill("Exception")}</b></div></section></div><section class="card section"><div class="split"><div><h2>Recent master ledger transactions</h2><p class="sub">Click a transaction to inspect settlement, counterparty and compliance details.</p></div><button class="button ghost" data-go="ledger">Open ledger</button></div>${ledgerTable(ledger.slice(0,5))}</section>`;bindLedger()}
function ledgerTable(data){return rows(["TX ID","Date time","Client","Type","Asset","IN","OUT","Rate","Desk","Status","KYC / AML"],data.map(r=>[txLink(r),r.date,r.client,pill(r.type.startsWith("Fiat")?"BUY":"SELL"),r.asset,r.fiatIn?`<span class="amount in">${money(r.fiatIn)}</span>`:`<span class="amount in">${r.cryptoIn.toLocaleString()} ${r.asset}</span>`,r.fiatOut?`<span class="amount out">${money(r.fiatOut)}</span>`:`<span class="amount out">${r.cryptoOut.toLocaleString()} ${r.asset}</span>`,r.rate.toLocaleString(),r.desk,pill(r.status),`${pill(r.kyc)} ${pill(r.aml)}`]))}
function ledgerKpis(records){const volumeValue=records.reduce((sum,r)=>sum+volume(r),0),fiatIn=records.reduce((sum,r)=>sum+r.fiatIn,0),fiatOut=records.reduce((sum,r)=>sum+r.fiatOut,0);return `<div class="ledger-kpis"><div class="kpi"><label>OTC total volume</label><strong>${money(volumeValue)}</strong></div><div class="kpi"><label>Fiat IN</label><strong>${money(fiatIn)}</strong></div><div class="kpi"><label>Fiat OUT</label><strong>${money(fiatOut)}</strong></div><div class="kpi"><label>Transaction count</label><strong>${records.length}</strong></div></div>`}
function ledgerView(){const options=values=>`<option value="">All</option>${values.map(value=>`<option value="${value}">${value}</option>`).join("")}`,clientOptions=[...new Set(ledger.map(r=>r.client))],deskOptions=[...new Set(ledger.map(r=>r.desk))],assetOptions=[...new Set(ledger.map(r=>r.asset))],typeOptions=[...new Set(ledger.map(r=>r.type))],statusOptions=[...new Set(ledger.map(r=>r.status))];view.innerHTML=title("Master Transaction Ledger","Single source of truth for all daily, weekly, monthly, AUM and export views.",`<button class="button green" id="export-ledger">Export CSV</button>`)+`<section class="card ledger-filter-panel"><div class="ledger-filters"><label>Client<select id="client-filter">${options(clientOptions)}</select></label><label>Desk<select id="desk-filter">${options(deskOptions)}</select></label><label>Asset<select id="asset-filter">${options(assetOptions)}</select></label><label>Transaction type<select id="type-filter">${options(typeOptions)}</select></label><label>Settlement status<select id="status-filter">${options(statusOptions)}</select></label><label>KYC / AML<select id="compliance-filter"><option value="">All</option><option value="verified-clear">Verified / Clear</option><option value="review">Review</option><option value="hold">Hold</option></select></label><label class="search-filter">Search TX ID / Client / Bank Ref / TXID<input id="search" placeholder="OTC-2026..."></label></div></section><div id="ledger-kpis">${ledgerKpis(ledger)}</div><div class="ledger-summary"><strong id="ledger-count">${ledger.length} transactions</strong><button class="button ghost" id="reset-ledger">Reset filters</button></div><section class="card" id="ledger-results">${ledgerTable(ledger)}</section>`;bindLedger();["#search","#client-filter","#desk-filter","#asset-filter","#type-filter","#status-filter","#compliance-filter"].forEach(selector=>{const el=document.querySelector(selector);el.addEventListener(el.tagName==="INPUT"?"input":"change",filterLedger)});document.querySelector("#reset-ledger").onclick=()=>{["#search","#client-filter","#desk-filter","#asset-filter","#type-filter","#status-filter","#compliance-filter"].forEach(selector=>document.querySelector(selector).value="");filterLedger()};document.querySelector("#export-ledger").onclick=()=>alert("Local export preparation is ready. Connect a governed report service for production downloads.")}
function filterLedger(){const value=id=>document.querySelector(id).value,query=value("#search").toLowerCase(),client=value("#client-filter"),desk=value("#desk-filter"),asset=value("#asset-filter"),type=value("#type-filter"),status=value("#status-filter"),compliance=value("#compliance-filter");const found=ledger.filter(r=>{const complianceValue=`${r.kyc.toLowerCase()}-${r.aml.toLowerCase()}`;return(!query||Object.values(r).join(" ").toLowerCase().includes(query))&&(!client||r.client===client)&&(!desk||r.desk===desk)&&(!asset||r.asset===asset)&&(!type||r.type===type)&&(!status||r.status===status)&&(!compliance||complianceValue===compliance)});document.querySelector("#ledger-kpis").innerHTML=ledgerKpis(found);document.querySelector("#ledger-count").textContent=`${found.length} transactions`;document.querySelector("#ledger-results").innerHTML=found.length?ledgerTable(found):'<div class="empty">No matching transactions.</div>';bindLedger()}
function bindLedger(){document.querySelectorAll("[data-id]").forEach(el=>el.onclick=()=>detail(el.dataset.id));document.querySelectorAll("[data-go]").forEach(el=>el.onclick=()=>render(el.dataset.go))}
function clientCode(r){return `C${String(ledger.findIndex(item=>item.id===r.id)+10).padStart(3,"0")}`}
function operatorFor(r){return {"Desk 01":"Dewi Anggraini","Desk 02":"Siti Nurhaliza Putri","Desk 03":"Rizky Pratama","Desk 04":"Nadia Kusuma","Desk 05":"Fajar Aditya"}[r.desk]}
function counterpartyFor(r){return `${r.client} — ${operatorFor(r)}`}
function lpName(r){return {["LP-001"]:"LP-001 Wintermute",["LP-002"]:"LP-002 FalconX",["LP-003"]:"LP-003 Cumberland",["LP-004"]:"LP-004 Institutional Liquidity"}[r.lp]||r.lp}
function fullWalletAddress(r){const seed=(r.id.replace(/[^0-9a-f]/gi,"")+"8ca4a14fb498c500f34101246").toLowerCase();if(cryptoNetwork(r)==="BITCOIN")return `bc1q${seed.repeat(3).slice(0,38)}`;if(cryptoNetwork(r)==="TRC20")return `T${seed.toUpperCase().repeat(3).slice(0,33)}`;return `0x${seed.repeat(3).slice(0,40)}`}
function fullBlockchainHash(r){const seed=(r.id.replace(/[^0-9a-f]/gi,"")+"e9638bbfaade234212e7da4856bdc21227dbf109d021dd3e193cd718d7b924").toLowerCase();const hash=seed.repeat(4).slice(0,64);return cryptoNetwork(r)==="ERC20"?`0x${hash}`:hash}
function explorerUrl(r){const hash=fullBlockchainHash(r);return cryptoNetwork(r)==="TRC20"?`https://tronscan.org/#/transaction/${hash}`:cryptoNetwork(r)==="BITCOIN"?`https://mempool.space/tx/${hash}`:`https://etherscan.io/tx/${hash}`}
function tokenContract(r){if(r.asset==="BTC")return "Native Bitcoin asset";if(r.asset==="USDC")return cryptoNetwork(r)==="TRC20"?"USDC TRC20": "USDC ERC20 · 0xA0b8…eB48";return cryptoNetwork(r)==="TRC20"?"USDT TRC20 · TR7NHq…8q8" : "USDT ERC20 · 0xdAC1…31ec7"}
function settlementFinality(r){return r.status==="Settled"||r.status==="Reconciled"?"Final":"Awaiting settlement control"}
function detail(id){const r=ledger.find(x=>x.id===id);if(!r)return;const fiatAmount=r.fiatIn||r.fiatOut,crypto=cryptoAmount(r),direction=r.fiatIn>0?"IN":"OUT",order=r.type.startsWith("Fiat")?"BUY":"SELL",spread="0.28%",fee="0.20%",revenue=Math.round(fiatAmount*.0028),network=cryptoNetwork(r),status=pill(r.status),hash=fullBlockchainHash(r);modal.hidden=false;modal.innerHTML=`<article class="dialog transaction-dialog" role="dialog" aria-modal="true" aria-label="Transaction detail ${r.id}"><header class="dialog-head"><div><h2>${r.id}</h2><p class="sub">Transaction Detail</p></div><div class="dialog-actions">${status}<button class="close" id="close" aria-label="Close transaction detail">×</button></div></header><div class="settlement-legs"><section><label>Fiat leg</label><strong>${money(fiatAmount)}</strong><span>${direction} · ${fiatRail(r)}</span></section><section><label>Crypto leg</label><strong>${crypto.toLocaleString()} ${r.asset}</strong><span>${cryptoDirection(r)} · ${network}</span></section></div><dl class="detail-list">${[["Date / time",`${r.date} WIB`],["Client",`${r.client} (${clientCode(r)})`],["Counterparty",counterpartyFor(r)],["Type",`${pill(order)} ${r.type}`],["Rate",`IDR ${r.rate.toLocaleString()} / ${r.asset}`],["Broker spread",spread],["Broker fee",fee],["Broker revenue",money(revenue)],["Desk",r.desk],["Liquidity provider",lpName(r)],["Bank",bankName(r)],["Bank reference",r.bank],["Network",network],["Token contract",tokenContract(r)],["Wallet address",`<code>${fullWalletAddress(r)}</code>`],["Blockchain TXID",`<a class="hash-link" href="${explorerUrl(r)}" target="_blank" rel="noreferrer">${hash} ↗</a>`],["Confirmations",cryptoConfirmations(r)],["Settlement finality",settlementFinality(r)],["Wallet screening",r.aml==="Clear"?pill("Clear"):pill(r.aml)],["KYC / AML",`${pill(r.kyc)} ${pill(r.aml)}`],["Operator",operatorFor(r)]].map(x=>`<div><dt>${x[0]}</dt><dd>${x[1]}</dd></div>`).join("")}</dl><footer class="dialog-footer"><button class="button ghost" id="close-footer">Close</button><button class="button" id="voucher">⇩ Download Transaction Voucher</button></footer></article>`;const close=()=>modal.hidden=true;document.querySelector("#close").onclick=close;document.querySelector("#close-footer").onclick=close;document.querySelector("#voucher").onclick=()=>alert(`Local transaction voucher prepared for ${r.id}.`);modal.onclick=event=>{if(event.target===modal)close()}}
function bankName(r){return r.bank.startsWith("MDR")?"Bank Mandiri":r.bank.startsWith("BCA")?"Bank BCA":r.bank.startsWith("BRI")?"Bank BRI":"Bank BNI"}
function fiatRail(r){return r.bank.startsWith("BCA")?"BI-FAST":r.bank.startsWith("WIRE")?"SWIFT":r.bank.startsWith("BRI")?"RTGS":"RTGS"}
function fiatKpis(records){const fiatIn=records.reduce((sum,r)=>sum+r.fiatIn,0),fiatOut=records.reduce((sum,r)=>sum+r.fiatOut,0),net=fiatIn-fiatOut;return `<div class="ledger-kpis fiat-kpis"><div class="kpi"><label>Fiat IN</label><strong>${money(fiatIn)}</strong></div><div class="kpi"><label>Fiat OUT</label><strong>${money(fiatOut)}</strong></div><div class="kpi"><label>Net flow</label><strong>${money(net)}</strong></div><div class="kpi"><label>Transaction count</label><strong>${records.length}</strong></div></div>`}
function fiatBankTable(records){const banks=["Bank Mandiri","Bank BCA","Bank BNI","Bank BRI"].map(bank=>{const group=records.filter(r=>bankName(r)===bank),fiatIn=group.reduce((sum,r)=>sum+r.fiatIn,0),fiatOut=group.reduce((sum,r)=>sum+r.fiatOut,0);return[bank,String(group.length),money(fiatIn),money(fiatOut),money(fiatIn-fiatOut)]});return rows(["Bank","Transactions","IN","OUT","Net flow"],banks)}
function fiatTransactionTable(records){return rows(["TX ID","Date / time","Client","IN / OUT","Amount","IDR","Bank","Rail","Bank reference","KYC / AML","Status"],records.map(r=>{const amount=r.fiatIn||r.fiatOut,direction=r.fiatIn>0?"in":"out";return[txLink(r),r.date,r.client,`<span class="direction ${direction}">${direction.toUpperCase()}</span>`,`<span class="amount ${direction}">IDR ${amount.toLocaleString("id-ID")}</span>`,`<span class="amount ${direction}">${money(amount)}</span>`,bankName(r),fiatRail(r),r.bank,`${pill(r.kyc)} ${pill(r.aml)}`,pill(r.status)]}))}
function fiatTransactions(records){return `<section class="card fiat-transactions"><div class="section-title"><span>Fiat Ledger</span><small>${records.length} transactions</small></div><div id="fiat-transaction-results">${fiatTransactionTable(records)}</div></section>`}
function fiatView(){view.innerHTML=title("Fiat Ledger","RTGS · BI-FAST · SKNBI · SWIFT",`<button class="button ghost" id="fiat-csv">⇩ CSV</button>`)+`<section class="card fiat-filter-panel"><div class="fiat-filters"><div><span class="eyebrow">Period</span><div class="period-switch" id="fiat-period"><button class="active">Today</button><button>Weekly</button><button>Monthly</button><button>Since inception</button><button>Custom Range</button></div></div><label>Rail<select id="rail-filter"><option value="">All</option><option>RTGS</option><option>BI-FAST</option><option>SKNBI</option><option>SWIFT</option></select></label><label>IN / OUT<select id="fiat-direction"><option value="">All</option><option value="in">IN</option><option value="out">OUT</option></select></label></div></section><div id="fiat-kpis">${fiatKpis(ledger)}</div><section class="card fiat-breakdown"><div class="section-title">Bank Breakdown</div><div id="fiat-results">${fiatBankTable(ledger)}</div></section>${fiatTransactions(ledger)}`;document.querySelectorAll("#fiat-period button").forEach(button=>button.onclick=()=>{document.querySelectorAll("#fiat-period button").forEach(item=>item.classList.remove("active"));button.classList.add("active")});document.querySelector("#rail-filter").onchange=filterFiat;document.querySelector("#fiat-direction").onchange=filterFiat;document.querySelector("#fiat-csv").onclick=()=>alert("Local Fiat Ledger CSV preparation is ready.");bindLedger()}
function filterFiat(){const rail=document.querySelector("#rail-filter").value,direction=document.querySelector("#fiat-direction").value;const found=ledger.filter(r=>(!rail||fiatRail(r)===rail)&&(!direction||(direction==="in"?r.fiatIn>0:r.fiatOut>0)));document.querySelector("#fiat-kpis").innerHTML=fiatKpis(found);document.querySelector("#fiat-results").innerHTML=fiatBankTable(found);document.querySelector(".fiat-transactions").outerHTML=fiatTransactions(found);bindLedger()}
function cryptoNetwork(r){if(r.asset==="BTC")return "BITCOIN";if(r.asset==="USDC")return "ERC20";return r.id.endsWith("17")?"ERC20":"TRC20"}
function cryptoAddress(r){const network=cryptoNetwork(r);if(network==="BITCOIN")return "bc1q0dbfa1…0c0424";if(network==="TRC20")return "T"+(r.id.replace(/[^0-9]/g,"")+"B635A7D85").slice(0,14)+"…101246";return "0x"+(r.id.replace(/[^0-9]/g,"")+"8ebf5095").slice(0,14)+"…364d3d"}
function cryptoConfirmations(r){return r.status==="Processing"?"0":r.status==="Pending"?"5":r.status==="Exception"?"0":"12"}
function cryptoDirection(r){return r.cryptoIn>0?"IN":"OUT"}
function cryptoAmount(r){return r.cryptoIn||r.cryptoOut}
function cryptoKpis(records){const usdtIn=records.filter(r=>r.asset==="USDT"&&r.cryptoIn>0).reduce((sum,r)=>sum+r.cryptoIn,0),usdtOut=records.filter(r=>r.asset==="USDT"&&r.cryptoOut>0).reduce((sum,r)=>sum+r.cryptoOut,0),usdcIn=records.filter(r=>r.asset==="USDC"&&r.cryptoIn>0).reduce((sum,r)=>sum+r.cryptoIn,0),btcIn=records.filter(r=>r.asset==="BTC"&&r.cryptoIn>0).reduce((sum,r)=>sum+r.cryptoIn,0);return `<div class="ledger-kpis crypto-kpis"><div class="kpi"><label>Crypto IN (USDT)</label><strong>${usdtIn.toLocaleString()} USDT</strong><span>${money(usdtIn*15850)}</span></div><div class="kpi"><label>Crypto OUT (USDT)</label><strong>${usdtOut.toLocaleString()} USDT</strong><span>${money(usdtOut*15850)}</span></div><div class="kpi"><label>USDC / BTC IN</label><strong>${usdcIn.toLocaleString()} USDC</strong><span>${btcIn.toFixed(4)} BTC</span></div><div class="kpi"><label>Transaction count</label><strong>${records.length}</strong><span>On-chain legs</span></div></div>`}
function cryptoTable(records){return rows(["TX ID","Date / time","Client","IN / OUT","Asset","Amount","Network","Wallet address","Blockchain TXID","Confirmations","KYC / AML","Status"],records.map(r=>{const direction=cryptoDirection(r).toLowerCase();return[txLink(r),r.date,r.client,`<span class="direction ${direction}">${direction.toUpperCase()}</span>`,r.asset,`<span class="amount ${direction}">${cryptoAmount(r).toLocaleString()} ${r.asset}</span>`,cryptoNetwork(r),cryptoAddress(r),r.txid,cryptoConfirmations(r),`${pill(r.kyc)} ${pill(r.aml)}`,pill(r.status)]}))}
function cryptoTransactions(records){return `<section class="card crypto-transactions"><div class="section-title"><span>Crypto Ledger</span><small>${records.length} on-chain legs</small></div><div id="crypto-transaction-results">${cryptoTable(records)}</div></section>`}
function cryptoView(){view.innerHTML=title("Crypto Ledger","TRC20 · ERC20 · BEP20 · BTC",`<button class="button ghost" id="crypto-csv">⇩ CSV</button>`)+`<section class="card crypto-filter-panel"><div class="crypto-filters"><div><span class="eyebrow">Period</span><div class="period-switch" id="crypto-period"><button class="active">Today</button><button>Weekly</button><button>Monthly</button><button>Since inception</button><button>Custom Range</button></div></div><label>Asset<select id="crypto-asset"><option value="">All</option><option>USDT</option><option>USDC</option><option>BTC</option></select></label><label>Network<select id="crypto-network"><option value="">All</option><option>TRC20</option><option>ERC20</option><option>BITCOIN</option></select></label></div></section><div id="crypto-kpis">${cryptoKpis(ledger)}</div>${cryptoTransactions(ledger)}`;document.querySelectorAll("#crypto-period button").forEach(button=>button.onclick=()=>{document.querySelectorAll("#crypto-period button").forEach(item=>item.classList.remove("active"));button.classList.add("active")});document.querySelector("#crypto-asset").onchange=filterCrypto;document.querySelector("#crypto-network").onchange=filterCrypto;document.querySelector("#crypto-csv").onclick=()=>alert("Local Crypto Ledger CSV preparation is ready.");bindLedger()}
function filterCrypto(){const asset=document.querySelector("#crypto-asset").value,network=document.querySelector("#crypto-network").value;const found=ledger.filter(r=>(!asset||r.asset===asset)&&(!network||cryptoNetwork(r)===network));document.querySelector("#crypto-kpis").innerHTML=cryptoKpis(found);document.querySelector(".crypto-transactions").outerHTML=cryptoTransactions(found);bindLedger()}
function simple(kind){const data={fiat:["Fiat Ledger","Bank settlement positions across Mandiri, BCA, BRI and wire rails",["Bank reference","Rail","Expected","Actual","Status"],ledger.map(r=>[r.bank,r.bank.startsWith("BCA")?"BI FAST":"RTGS / Wire",money(volume(r)),money(volume(r)),r.status])],clients:["B2B Corporate Clients","Institutional client directory with volumes, AUM and compliance state",["Client ID","Entity name","Tier","Transactions","Volume","Net flow","AUM","Status"],clients],reconciliation:["Reconciliation","Bank and on-chain balances measured against the master ledger",["Control","Expected","Actual","Difference","Status"],[["Bank accounts","Rp 84.2 B","Rp 84.2 B","Rp 0","Reconciled"],["USDT TRC20","3,710,000","3,710,000","0","Reconciled"],["USDC ERC20","2,560,000","2,560,000","0","Reconciled"],["BTC settlement","0.154 BTC","0.154 BTC","0","Reconciled"],["Exception reserve","Rp 8.9 B","Rp 8.9 B","0","Exception"]]],compliance:["KYC AML Monitoring","Client and transaction monitoring escalation queue",["Case","Client","Control","Risk","Disposition"],[["AML-0042","Kencana Asset Mandiri","Wallet screening","Medium","Review"],["AML-0041","Sarana Niaga Digital","Source of funds","High","Hold"],["AML-0039","Garuda Prima Capital","Sanctions rescreen","Low","Clear"]]],audit:["Audit Trail","Append-only record. Use void, cancellation or reversal - never hard delete.",["Timestamp","User","Action","Object","Old value","New value"],[["14:42","Desk Operator","Settle transaction","OTC-2026-0218","Processing","Settled"],["13:07","Compliance Lead","Update screening","AML-0041","Review","Hold"],["11:16","Treasury Manager","Reconcile bank","OTC-2026-0217","Pending","Reconciled"]]]}[kind];view.innerHTML=title(data[0],data[1],`<button class="button green">Export view</button>`)+`<section class="card section">${rows(data[2],data[3])}</section>`}
function deskView(){view.innerHTML=title("OTC Desk Configuration","Editable pricing controls for Desk 01 through Desk 05. Each change should become an audit record.",`<button class="button green" id="save-desks">Save configuration</button>`)+`<section class="card section"><div class="desk-grid"><div class="head">CONTROL</div>${["Desk 01","Desk 02","Desk 03","Desk 04","Desk 05"].map(x=>`<div class="head">${x}</div>`).join("")}${desks.map(r=>`<div>${r[0]}</div>${r.slice(1).map((x,i)=>`<div><input value="${x}" aria-label="${r[0]} desk ${i+1}"></div>`).join("")}`).join("")}</div><div class="grid section"><div><h2>Live commercial calculation</h2><div class="metric"><span>Client price</span><b>15,855</b></div><div class="metric"><span>Gross spread</span><b>0.28%</b></div><div class="metric"><span>Desk revenue</span><b>Rp 184.6 M</b></div><div class="metric"><span>Broker revenue</span><b>Rp 52.3 M</b></div></div><div><h2>Control requirement</h2><p class="sub">Save actions must record timestamp, authorized user, old value, new value and approval boundary. Historical transactions are never overwritten.</p></div></div></section>`;document.querySelector("#save-desks").onclick=()=>alert("Local configuration saved for preview. Production save must create an immutable audit event.")}
function reports(kind="Reports"){view.innerHTML=title(kind,"Generate daily, weekly, monthly and since-inception summaries from the master ledger.",`<button class="button green">Generate report</button>`)+`<div class="grid section"><section class="card"><h2>Report period</h2><p class="sub">All report views calculate from the same ledger.</p><div class="filters"><select><option>Daily</option><option>Weekly</option><option>Monthly</option><option>Since inception</option></select><input value="24/10/2026"><button class="button">Generate</button></div><div class="bars section">${[["Transaction volume",82],["Fiat flow",68],["Crypto flow",74],["Desk revenue",55],["Reconciliation",99]].map(x=>`<div class="bar-row"><span>${x[0]}</span><div class="bar"><i style="width:${x[1]}%"></i></div><b>${x[1]}%</b></div>`).join("")}</div></section><section class="card"><h2>Export package</h2><p class="sub">Structured output includes executive summary, transaction ledger, fiat and crypto flows, five desks, clients, AUM, reconciliation, KYC AML and audit trail.</p><button class="button green">Excel XLSX</button> <button class="button ghost">CSV</button> <button class="button ghost">PDF</button></section></div>`}
function aum(){view.innerHTML=title("AUM Managed Assets","IDR equivalent reserve breakdown using configurable exchange-rate controls.")+`<div class="kpis section"><div class="kpi"><label>Current AUM</label><strong>Rp 312.8 B</strong><span>Current valuation</span></div><div class="kpi"><label>Opening AUM</label><strong>Rp 289.4 B</strong><span>Period opening</span></div><div class="kpi"><label>Net inflow</label><strong>Rp 36.2 B</strong><span>Ledger derived</span></div><div class="kpi"><label>Net outflow</label><strong>Rp 12.8 B</strong><span>Ledger derived</span></div></div><section class="card">${rows(["Asset","Quantity","IDR equivalent","Reserve status"],[["IDR","118.9 B","Rp 118.9 B","Reconciled"],["USD","4.2 M","Rp 66.7 B","Reconciled"],["USDT","5.7 M","Rp 90.7 B","Reconciled"],["USDC","1.8 M","Rp 28.2 B","Reconciled"],["BTC","0.154","Rp 1.6 B","Review"]])}</section>`}
function exportsView(){reports("Export Center")}
function settings(){view.innerHTML=title("Settings","Controlled reference configuration for management users.")+`<section class="card section"><div class="metric"><span>Default reporting currency</span><b>IDR</b></div><div class="metric"><span>Primary exchange rate reference</span><b>15,850 IDR USD</b></div><div class="metric"><span>Desk approval requirement</span><b>Dual approval</b></div><div class="metric"><span>Audit policy</span><b>Void reversal only</b></div></section>`}
function render(name){document.querySelectorAll(".nav").forEach(n=>n.classList.toggle("active",n.dataset.view===name));({dashboard,ledger:ledgerView,fiat:fiatView,crypto:cryptoView,clients:()=>simple("clients"),desks:deskView,reports, aum,reconciliation:()=>simple("reconciliation"),compliance:()=>simple("compliance"),exports:exportsView,audit:()=>simple("audit"),settings})[name]()}
document.querySelectorAll(".nav").forEach(n=>n.onclick=()=>render(n.dataset.view));render("dashboard");
